(window.webpackJsonp=window.webpackJsonp||[]).push([[4,321],{612:function(e,a,n){e.exports={}},661:function(e){e.exports=JSON.parse(`[{"id":58948,"created_at":"2026-11-24T00:00:00+00:00","updated_at":"2026-11-24T16:17:45.455489+00:00","job_link":"/tefl-jobs-centre/job/teach-english-taiwan-58948/","title":"Kindergarten English Teacher","company_tagline":"With 150 children (6-12 yrs) in 10 classes, the major topic is to help them complete their homework plus 320 minutes English teaching per week.","thumbnail":"https://images.unsplash.com/photo-1657724738971-0caa65a15661?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHw3fHxUYWljaHVuZyUyQyUyMFRhaXdhbiUyQyUyMFJlcHVibGljJTIwb2YlMjBDaGluYXxlbnwwfDB8fHwxNzc0MzgzNTQ5fDA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Taiwan","contract_type":"Full Time","description":"<p>An exciting opportunity to experience a new culture, you will be based in Taichung City, Taiwan, teaching English to eager young children and earn a good salary. Begin by joining in the Chinese New Year celebrations! The long lead in time is to allow for the visa process to be completed. </p><p><br></p><p>Full time post, Mon-Fri </p>","featured":true},{"id":59409,"created_at":"2026-11-24T00:00:00+00:00","updated_at":"2026-11-24T11:58:50.03905+00:00","job_link":"/tefl-jobs-centre/job/teach-english-indonesia-59409/","title":"Teach English","company_tagline":"With over 30 years of experience, it is a global leader in education, inspiring young minds through language learning and cultural experiences","thumbnail":"https://images.unsplash.com/photo-1718729362445-51d2da1ee7a7?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHw0fHxKYWthcnRhfGVufDB8MHx8fDE3OTUxNzE3OTR8MA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Indonesia","contract_type":"Full Time","description":"<p>English 1 is an international organization that operates mostly on a franchise basis. As one of the largest franchise groups, they are recruiting staff to be located across the Jakarta Greater Area, in one of our centers.</p><p>They have 20 centers spreading across the region. There are 8 centers in Jakarta, the Metropolis. (Pluit, Tebet, Tanjung, Duren, Puri Indah, Tanjung Barat, Pondok Indah, Green Sedayu Mall, PIK), 7 in Tangerang, a suburb of Jakarta (BSD, Gading Serpong, Tangerang City, Ciledug, Graha Alam Sutera, Green Lake City, and Cisauk), 4 in Bogor, a satellite city near Jakarta (Bogor Pajajaran, Taman Yasmin, Cibinong, and Sentul) and 1 in Depok (Cinere)</p><p><br></p><p>They are looking for the following positions:</p><p>- Academic Manager</p><p>- Teacher Coordinator</p><p>- Senior Teacher</p><p>- English Teacher</p><p><br></p><p><strong>Job Description for Teachers:</strong></p><p>- Plan and deliver the highest quality of lessons</p><p>- Ensure the student has the best experience possible</p><p>- Monitor student's development and communicate frequently with the parents</p><p>- Strive to develop professional skillset via attending workshops, training and self-learning tasks</p><p>- Teach young learners (preschool - teens)</p><p><br></p><p><strong>Additional Job Description for Specific Positions:</strong></p><p>- Academic Manager: Oversee the academic quality to ensure high teaching standards, managing a team of teachers and contribute to both academic excellence and operational efficiency.</p><p>- Senior Teacher: Training new teachers and maintaining the development of teaching skills for the academic team.</p><p>- Teacher Coordinator: Supports the academic manager and senior teacher in ensuring a smooth academic operations by coordinating teacher schedule, facilitate communication between staff and management, support teachers and collaborate with all academic team.</p>","featured":true},{"id":58955,"created_at":"2026-11-20T00:00:00+00:00","updated_at":"2026-11-20T13:58:35.017311+00:00","job_link":"/tefl-jobs-centre/job/teach-english-south-korea-58955/","title":"Private school positions all over Korea","company_tagline":"A boutique, American-owned and operated ESL recruitment agency founded in 2006 and based in Korea.","thumbnail":"https://images.unsplash.com/photo-1668737488609-68b4f816dfe3?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwyNXx8U2VvdWwlMkMlMjBLb3JlYXxlbnwwfDB8fHwxNzk0OTU2Njg1fDA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"South Korea","contract_type":"Full Time","description":"<h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">They have private school positions all over Korea. </span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">They have jobs in Seoul, Gyeonggido, Incheon, Daegu, Busan, and many other cities, too!</span></h2><p><br></p><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">Job Overview:</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">1. School area: All over Korea</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">2. Working hours: M-F 9:00-6:00 OR similar (60 min lunch, + breaks + planning periods)</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">3. Pay: 2.5~3.1 million KRW (depends on exp.)</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">4. Age group: Kinder (5-7-year-olds) and 1st-grade elementary up to grade 6</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">5. Start: March 1st, 2027 (training for a week before the start date)</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">6. Benefits: Standard</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7 &nbsp; Monthly Pay: 2.57 M- 3.1 M KRW, but negotiable depending on experience</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7 &nbsp; Single-furnished housing or a housing stipend (400,000 won)</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7 &nbsp; Flight Ticket Reimbursement of up to 1 million KRW after 90 days of initiation of the work (except for teachers who are already in Korea)</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7 11 paid vacation days per year, in addition to national holidays set by the schools</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7&nbsp; &nbsp; Severance bonus upon the completion of the 1-year contract</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7&nbsp; &nbsp; Medical Insurance: 50% of the national insurance premium is paid for by our school</span></h2><h2><span style=\\"background-color: transparent; color: rgb(0, 0, 0);\\">\xB7 &nbsp; &nbsp; Monthly contribution to the National Pension Fund.</span></h2><h2>Schools normally have a few to dozens of expats.</h2>","featured":true},{"id":58954,"created_at":"2026-11-20T00:00:00+00:00","updated_at":"2026-11-20T13:57:01.433447+00:00","job_link":"/tefl-jobs-centre/job/teach-english-south-korea-58954/","title":"Teach English in South Korea! Work with Expats!","company_tagline":"Expat-owned boutique ESL agency placing teachers in Korea since 2005. Brad & Yumi guide you from application to arrival. No BS, no drama \u2014 just great teachers at great schools.","thumbnail":"https://images.unsplash.com/photo-1506816561089-5cc37b3aa9b0?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwyNHx8U2VvdWwlMkMlMjBLb3JlYXxlbnwwfDB8fHwxNzc0MzUxNTczfDA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"South Korea","contract_type":"Full Time","description":"<p class=\\"ql-align-center\\">  <strong style=\\"color: white;\\">\u{1F1F0}\u{1F1F7}&nbsp;Teach English in South Korea! Work w/Expats!</strong></p><p class=\\"ql-align-center\\"><span style=\\"color: rgb(168, 200, 232);\\">$2,000 \u2013 $2,600 USD/mo&nbsp;\xB7&nbsp;Free Housing&nbsp;\xB7&nbsp;Airfare&nbsp;\xB7&nbsp;Benefits</span></p><p class=\\"ql-align-center\\"><em style=\\"color: rgb(143, 191, 224);\\">Placed by TeachEnglishInKorea.org (TEIK)&nbsp;\xB7&nbsp;Expat-Owned &amp; Operated Since 2005</em></p><p>  </p><p><span style=\\"color: rgb(34, 34, 34);\\">Are you a TEFL-certified English speaker ready for an incredible adventure in South Korea? This is a boutique, expat-owned recruitment agency that has been placing outstanding teachers at high-quality Korean schools since 2005. They work with hagwons, public schools, kindergartens, and universities across Seoul, Gyeonggido, Busan, Incheon, Daegu, Daejeon, and beyond, and they'd love to find the perfect position for you. </span></p><p><br></p><p><strong style=\\"color: rgb(31, 78, 121);\\">Why You'll Love Teaching with TEIK</strong></p><p><br></p><p><strong style=\\"color: rgb(46, 117, 182);\\">They Are Expats \u2014 Just Like You!</strong></p><p><span style=\\"color: rgb(34, 34, 34);\\">TEIK is run by Brad and Yumi \u2014 an American-Korean husband-and-wife team who have both lived, taught, and worked in Korea for over 20 years combined. They understand exactly what teachers face because they have been through it themselves. They speak your language - literally and culturally.</span></p><p><strong style=\\"color: rgb(46, 117, 182);\\">Quality Over Quantity \u2014 Always</strong></p><p><span style=\\"color: rgb(34, 34, 34);\\">They are selective about the schools they work with. Every school in the TEIK network has a proven track record of paying teachers on time, providing proper furnished housing, and honoring their contracts \u2014 drama-free. They turn down schools that don't meet their standards, and they are always honest with you about every position.</span></p><p><strong style=\\"color: rgb(46, 117, 182);\\">Full Support from Application to Arrival</strong></p><p><span style=\\"color: rgb(34, 34, 34);\\">They guide you through every step of the process \u2014 document preparation, FBI criminal background check, visa application, interview scheduling, flights, and arrival in Korea. Their support doesn't end when you board the plane. Teachers can contact them at any time, and they respond quickly!</span></p><p><strong style=\\"color: rgb(46, 117, 182);\\">A Real Community \u2014 The TEIK Network</strong></p><p><span style=\\"color: rgb(34, 34, 34);\\">One of the things that sets TEIK apart is their commitment to community. Before you arrive, they introduce you to current TEIK teachers in Korea so you land with a social network already in place. Twice a year \u2014 every Spring and Fall \u2014 they host a TEIK Networking Dinner for up to 60 of their teachers: a warm, fun evening of food, drinks, and genuine friendship where new teachers meet experienced ones and lifelong connections are made.</span></p>","featured":true},{"id":58210,"created_at":"2026-11-19T00:00:00+00:00","updated_at":"2026-11-19T12:25:30.976937+00:00","job_link":"/tefl-jobs-centre/job/teach-english-cambodia-58210/","title":"Teach in Cambodia! No degree needed!","company_tagline":"Whether you are a seasoned teacher or considering a career in TEFL, their team of recruiting experts will assist you in making your dreams and aspirations for a TEFL career come true.","thumbnail":"https://images.unsplash.com/photo-1526324585411-e24d5ba61edd?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHw2fHxQaG5vbSUyMFBlbmglMkMlMjBDYW1ib2RpYXxlbnwwfDB8fHwxNzE4ODAyMDIxfDA&ixlib=rb-4.0.3?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Cambodia","contract_type":"Internship","description":"<p>Can you swim? Good! Because you are about to be thrown into the deep end of your TEFL career!</p><p>To be clear, this is an internship in that the program provides a lot of support from obtaining the correct visa, pre-departure assistance, proper training and orientation (you will be put in real classes, with real students), cultural immersion workshops to make sure you know your way around Cambodia, finding long-term accommodation, setting up local sim and bank account and support throughout your entire teaching contract. But here's the thing, you won\u2019t be a teacher\u2019s assistant or a coach in a language centre. At the end of the teaching practicum you will be placed in a well-paid English teaching JOB, where you will be conducting your own classes. Challenge accepted!</p><p><br></p><p>Now we all know the saying \u201Cwith great power \u2026&nbsp;COMES A PRETTY DECENT SALARY\u201D, or something like that! Teaching salaries in Cambodia range between US $800 - $1,200. With the low cost of living, you will be able to pay all your usual expenses, save some money, and even have a beer every now and then.</p><p><br></p><p>They only ask for one thing\u2026 go and inspire! Touch the hearts and minds of Cambodian children through your English classes and build their confidence in English listening, speaking, reading, and writing, just for about 25 hours per week.</p>","featured":true},{"id":48442,"created_at":"2026-11-18T00:00:00+00:00","updated_at":"2026-11-18T09:25:47.569576+00:00","job_link":"/tefl-jobs-centre/job/teach-english-south-korea-48442/","title":"Teach in S. Korea! $2K+ USD mo.","company_tagline":"The best run recruitment agency placing high-quality teachers at high-quality schools in S. Korea.","thumbnail":"https://cdn-wp.tefl.org/wp-content/uploads/2019/10/Busan-1.jpg","geolocation_country_long":"South Korea","contract_type":"Full Time","description":"<p>Teach in S. Korea!</p><p><br></p><p>$2,000-$2,600 USD mo. (Free housing, bonus, one-way airfare, pension, and National Health Insurance).\\n\\nThis company have been placing teachers in Korea since 2005 with zero complaints. They are a husband-and-wife team (Brad and Yumi) who have both taught, lived, and worked in Korea for TEIK since 2005. They pride themselves on being a boutique recruitment agency that always focuses on our teachers getting the best job opportunity that fits the teacher's qualifications, experience, and preferences. They are a very laid-back, low-pressure ex-pat owned and run agency.</p><p><br></p><p>TEIK&nbsp;is the best run recruitment agency placing high-quality teachers at high-quality schools. They only work with schools with an excellent track record for paying their teachers on time, drama-free, and honoring teachers' contracts. They are a boutique recruitment agency owned and run by ex-pats. Based in Incheon, Korea, they focus on the 'QUALITY' of teachers rather than the placement 'QUANTITY' of teachers. So, if you are a diligent college graduate who loves children, is seeking an adventure abroad, wants to save a lot of money, and is flexible, then be sure to contact them. Please email your resume, current smiling passport-style photo, and fill out the 2-minute job application on their website below.</p><p><br></p><p>Their goal is to send quality teachers to quality schools, period. &nbsp;If you want to work with an American-owned and run recruitment agency that has lived, taught, and placed teachers in Korea since 2005, they would love the opportunity to work with you. Unlike other recruiters, at TEIK pride themselves on helping build their teacher's social network by introducing new teachers to their current teachers living in Korea to help develop a sense of community and help their teachers smoothly transition into a new country's culture and adventure. Most recruiters are Korean, Korean schools, or Korean-owned agencies, and they care most about the school and less about you. TEIK, on the other hand, is teacher-centric, where your needs come first. Other recruitment agencies believe that their job finishes when you arrive in Korea, but at TEIK they believe that their job is only half-finished after you come. They keep in contact with you throughout your entire placement, and they are here to give you advice and support when you need it. Check out the testimonials page and feel confident that you will be working with a company that you can understand and, more importantly, who can understand you. </p><p><br></p><p>They are looking to work with caring and honest individuals who have an adventurous spirit, love to travel, meet new people and who love teaching children. They hope you choose to go to Korea through them and have a fantastic experience like they did; you won't regret it!. </p><p><br></p><p>Most teachers can comfortably live in Korea on less than $1,000 per month, so you could easily save more than 50% of your monthly salary. You will also meet new lifelong Korean and international friends, learn about a fantastic culture, travel to several exotic neighboring countries, try excellent food, and have fun doing it!</p>","featured":true},{"id":59390,"created_at":"2026-11-17T00:00:00+00:00","updated_at":"2026-11-17T13:41:23.371539+00:00","job_link":"/tefl-jobs-centre/job/teach-english-austria-59390/","title":"TEACH ENGLISH IN EUROPE THIS WINTER","company_tagline":"An established educational organisation with over 35 years' experience delivering communicative English language programmes directly in schools across Europe.","thumbnail":"https://images.unsplash.com/photo-1757537091649-08f84c918220?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwzfHxBdXN0cmlhfGVufDB8MHx8fDE3OTQ0ODI3NTF8MA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Austria","contract_type":"Part Time","description":"<p><strong>Join Their Team for the Winter School Programme</strong></p><p><strong>Winter contracts in Austria and Germany | January\u2013March 2027</strong></p><p><br></p><p>Established over 35 years ago, they specialise in communicative, week-long English courses, delivered directly in schools across Europe. They work with local schools to give students an engaging and immersive English language experience, while offering teachers the opportunity to travel, teach and experience different European destinations.</p><p>As they prepare for their busiest programme period of the year, they are looking for eager, adaptable and enthusiastic teachers to join their Winter School team.</p><p><br></p><p><strong>Important eligibility requirements:</strong> Applicants must already have the legal right to work in the UK. They are unable to offer visa sponsorship. Their interviews are held in person in Central London, so applicants must also be able to attend.</p><p><br></p><p><strong>The Winter School Programme</strong></p><p>Their Winter School runs from late January through to March 2027, with the first contracts beginning the week commencing <strong>24 January</strong>.</p><p><br></p><p>They have a particularly busy programme this winter and are looking for teachers who can offer good flexibility and ideally commit to <strong>3\u20135 weeks or longer</strong>. There may also be opportunities to work in separate blocks, taking a short break between contracts before returning later in the season.</p><p><br></p><p>Individual one-week contracts are unlikely to be available, as their priority is to recruit teachers who can support the programme over several weeks.</p><ul><li>Contract lengths: Ideally 3\u20135 weeks or longer, depending on availability and course demand.</li><li>Working hours: Monday to Friday, approximately 25 teaching hours per week.</li><li>Students: Secondary school and 16+ learners.</li><li>Locations: Predominantly Austria, with some opportunities in Germany.</li><li>Start dates: From the week commencing 24 January 2027, with contracts continuing through February and March.</li></ul><p><br></p><p><strong>Who They're Looking For</strong></p><p>They welcome both newly qualified and experienced EFL teachers. Previous classroom experience is an advantage, but it is not essential for this programme.</p><p><br></p><p>They're particularly interested in teachers who are:</p><ul><li>Enthusiastic, energetic and keen to get involved in a communicative teaching programme.</li><li>Flexible and adaptable, with the confidence to work in different schools and teaching environments.</li><li>Comfortable travelling between locations, including weekend travel.</li><li>Happy working with a variety of secondary school and 16+ learners.</li><li>Reliable, organised and able to work independently while being part of a wider teaching team.</li><li>Interested in committing to several weeks of teaching, rather than just individual one-week placements.</li></ul><p>Their courses focus on communicative General English, with an emphasis on developing students' speaking and listening skills. Teachers are provided with structured materials and resources, so you won't need to develop an entire course from scratch.</p><p><br></p><p><strong>In-Person Interviews \u2013 Friday 11th December 2026</strong></p><p>Their next recruitment interview will take place on <strong>Friday 11th December in Central London</strong>.</p><p><br></p><p>They will be running morning and afternoon workshop-style sessions, each lasting approximately 1.5\u20132 hours. These provide an opportunity to meet the EiA team, learn more about the programme and teaching approach, and take part in collaborative activities.</p><p>Interviews are held in person only. They cannot offer online, telephone or individual alternative appointments.</p><p><br></p><p><strong>Please consider the travel involved before applying.</strong> Applicants travelling from outside London, elsewhere in the UK or from overseas must arrange and cover their own interview travel costs. Attendance does not guarantee a successful interview or an immediate contract offer.</p><p>Successful applicants will join their teaching pool and be considered for contracts according to their availability and their programme requirements. Teachers who are not immediately placed may still be considered for opportunities later in the winter season.</p>","featured":true},{"id":59387,"created_at":"2026-11-16T00:00:00+00:00","updated_at":"2026-11-16T15:13:09.002255+00:00","job_link":"/tefl-jobs-centre/job/teach-english-spain-59387/","title":"English language assistants (February-May 2027)","company_tagline":"An educational services company and English language learning program provider based in Spain.","thumbnail":"https://images.unsplash.com/photo-1679932347309-7beb937d5aff?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwxfHxHYWxpY2lhJTJDJTIwU3BhaW58ZW58MHwwfHx8MTc5NDM5MjY4Nnww&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Spain","contract_type":"Part Time","description":"<p><span style=\\"background-color: rgb(244, 244, 244); color: rgb(0, 0, 0);\\">Teach English in Galicia in spring 2027!</span></p><p><br></p><p><span style=\\"background-color: rgb(244, 244, 244); color: rgb(0, 0, 0);\\">Join this Language Assistant Programme, and help students build confidence in English, and gain valuable classroom experience. Discover Galicia's culture, improve your Spanish, and develop skills for your future career.</span></p><p><br></p><p><span style=\\"background-color: rgb(244, 244, 244); color: rgb(0, 0, 0);\\">Share your language. Discover a culture. Grow through experience.</span></p><p><br></p><p><span style=\\"background-color: rgb(244, 244, 244); color: rgb(0, 0, 0);\\">Apply now and make spring 2027 unforgettable!</span></p>","featured":true},{"id":58135,"created_at":"2026-11-05T00:00:00+00:00","updated_at":"2026-11-05T09:32:22.521403+00:00","job_link":"/tefl-jobs-centre/job/teach-english-china-58135/","title":"Native-level English Teaching Assistant","company_tagline":"A British company that has been providing quality education to local students for over 25 years. ","thumbnail":"https://images.unsplash.com/photo-1577871598838-a543ee47cd79?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwxMHx8SG9uZyUyMEtvbmd8ZW58MHwwfHx8MTcxMzE3Nzg3Nnww&ixlib=rb-4.0.3?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"China","contract_type":"Full Time","description":"<p>This school is looking for positive, energetic and dedicated native-level English speakers to join their team of over 20 teachers. Their positions offer a supportive working environment and provide a stepping stone into teaching in the city where \u2018East meets West\u2019.</p><p><br></p><p>They have a variety of positions available most of which are suitable for applicants who are new to teaching, as well as some that would appeal to applicants with previous experience. </p><p>Teachers in the kindergarten work with 1 age group (K1=3yrs/K2=4yrs/K3=5yrs) whilst teachers in the primary school work with different age groups (6yrs-12yrs). Classes cover all skills with an emphasis on reading, phonics and conversation. Short term contract: January \u2013 June 2027 (with on- the-job training).</p>","featured":true},{"id":59331,"created_at":"2026-11-05T00:00:00+00:00","updated_at":"2026-11-05T09:30:45.217161+00:00","job_link":"/tefl-jobs-centre/job/teach-english-china-59331/","title":"Teach English","company_tagline":"Founded in 2009, A language training centre in Changsha, China. They teach children, teenagers and adults in small classes of 6\u20138 students, focusing on practical English skills","thumbnail":"https://images.unsplash.com/photo-1712657826331-2d0f8b5a6453?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwzfHxDaGFuZ3NoYSUyQyUyMEh1bmFuJTJDJTIwQ2hpbmF8ZW58MHwwfHx8MTc5Mjc0MDE2MHww&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"China","contract_type":"Full Time","description":"<p>\u{1F4CB} Position Details</p><p><br></p><p>\u{1F522} Positions open: 2 foreign teachers</p><p>\u{1F3EB} School type: Private training school, SAFEA-authorized</p><p>\u{1F4CD} Location: Changsha city center</p><p>\u{1F467} Student ages: 3\u201320+ (kids, teenagers, university students, business professionals)</p><p>\u{1F550} Working hours: 40 hours/week on site. 60\u201380 teaching hours per month (approx. 15\u201320 hours/week) is the base teaching load. The after-tax salary of RMB 24,000 is based on around 25 teaching hours per week. Earnings increase with teaching hours; this is not fixed salary.</p><p>\u{1F465} Class size: 6\u20138 students</p><p>\u{1F680} Start date: Jan 2026</p><p>\u{1F464} Age requirement: 25\u201340 years old</p><p>\u{1F4B0} Monthly salary: RMB 18,000\u201324,000 [after tax]</p><p>\u23F3 Probation: 3 months, paid</p><p>\u{1F3E0} Accommodation: FREE brand-new private apartment</p><p>\u2708\uFE0F Flight allowance: Up to USD $1000 at contract completion</p><p>\u{1F6C2} Work visa: Provided</p><p>\u{1F3E5} Insurance: Accident insurance AND health insurance provided</p><p>\u{1F4DA} Pre-job training: Provided, with ongoing professional development</p><p>\u{1F3D6}\uFE0F Paid leave All Chinese statutory holidays</p><p>\u{1F389} Team benefits: Regular team-building activities and company trips</p><p>\u{1F696} Arrival support: Airport pickup, apartment check-in, residence registration and visa paperwork \u2014 all handled for you</p><p><br></p><p>\u{1F468}\u200D\u{1F3EB} What You\u2019ll Do</p><p><br></p><p>\u{1F4DA} Teaching &amp; Student Care</p><p>\u2022 Prepare and deliver engaging lessons in accordance with our curriculum \u{1F4D6}</p><p>\u2022 Teach kids, teenagers, university students, and business professionals \u{1F476}\u{1F466}\u{1F393}</p><p>\u2022 Assist with placement tests and trial/demo lessons for prospective students \u{1F9D1}\u200D\u{1F3EB}</p><p>\u2022 Supervise classes and keep accurate student performance records \u{1F4CA}</p><p>\u2022 Submit timely student progress reports \u{1F4DD}</p><p>\u2022 Attend parent-teacher meetings and keep parents updated on their child\u2019s progress \u{1F468}\u200D\u{1F469}\u200D\u{1F467}</p><p>\u2022 Organize and lead English corners, extracurricular clubs, and holiday events (Halloween \u{1F383}, Christmas \u{1F384}, Easter \u{1F95A}, etc.)</p><p>\u2022 Take part in summer/winter camps and occasional off-campus field trips \u{1F3D5}\uFE0F</p><p>\u2022 Provide reference letters and basic student counseling when needed \u2709\uFE0F</p><p><br></p><p>\u{1F4E3} Marketing &amp; Promotion</p><p>\u2022 Support the school\u2019s marketing activities \u2014 open days, seasonal campaigns, and community events \u{1F3AA}</p><p>\u2022 Take part in promotional photo and video shoots for our official social media (WeChat, Douyin, Xiaohongshu), sharing authentic moments of classroom life \u{1F3AC}</p><p>\u2022 Represent REA at occasional off-campus promotions, helping families get to know our school and teachers \u{1F91D}</p><p><br></p><p>\u{1F91D} Team &amp; Daily Operations</p><p>\u2022 Work closely with Chinese co-teachers and teaching assistants, and attend weekly staff meetings and training sessions \u{1F465}</p><p>\u2022 Keep your classroom tidy and prepare teaching materials and props in advance \u{1F9F0}</p><p>\u2022 Comply with Chinese laws and school policies, and keep your visa and residence documents valid \u2014 our foreign-affairs staff guide you through every renewal \u{1F6C2}</p><p>\u2022 Fulfill other reasonable duties assigned by the director to keep the school running smoothly \u{1F6E1}\uFE0F</p><p><br></p>","featured":true},{"id":59263,"created_at":"2026-10-06T14:13:29.319919+00:00","updated_at":"2026-10-06T15:18:46.71102+00:00","job_link":"/tefl-jobs-centre/job/teach-english-thailand-59263/","title":"Teach English in Thailand & Get Paid | Job Position ","company_tagline":"Gloading, a spin-off of Meddeas, creates supported teach-abroad experiences in Spain and Thailand, helping young people turn their plans to live, work and explore abroad into reality.","thumbnail":"https://images.unsplash.com/photo-1519451241324-20b4ea2c4220?ixid=M3w0MjYxNDJ8MHwxfHNlYXJjaHwxfHxUaGFpbGFuZHxlbnwwfDB8fHwxNzkxMjk1Nzc4fDA&ixlib=rb-4.1.0?crop=entropy&cs=tinysrgb&fit=max&fm=webp&q=50&w=800","geolocation_country_long":"Thailand","contract_type":"Full Time","description":"<p><strong>From FOMO to Teach English Abroad.</strong></p><p>You\u2019ve seen the videos. The weekend trips. The street food. The \u201CI moved abroad\u201D updates.</p><p><br></p><p>Now it\u2019s your turn.</p><p><br></p><p>Stop watching someone else live the experience and start creating your own. With their Teach English in Thailand program, you can move abroad, get paid to teach and experience everyday life in Thailand, not just travel through it.</p><p><br></p><p>Applications for their May 2027 intake are now open.</p><p><br></p><p><strong>The Job</strong></p><p><br></p><p>You\u2019ll work at a local school in Thailand, helping students build their confidence in English through conversation, games, activities and projects.</p><p><br></p><p>Depending on your academic background and your school\u2019s needs, you may also have the opportunity to teach subjects such as Maths, Science or Computer Science in English.</p><p><br></p><p>Your employment conditions are arranged with your Host School and include:</p><p><br></p><ul><li>A minimum salary of 30,000 THB per month</li><li>Accommodation provided by your school or an accommodation allowance, depending on your placement</li><li>A teaching position at a school in Thailand</li><li>A school year divided into two semesters: May\u2013September and October\u2013March</li></ul><p><br></p><p>Starting in May gives you the opportunity to experience the full Thai academic year.</p><p><br></p><p>And when you\u2019re not in the classroom? That part is yours.</p><p><br></p><p>Explore Thailand, discover a completely different culture and meet new people.</p><p><br></p><p><br></p><p><br></p>","featured":true}]`)}}]);

